'use strict';
const $=id=>document.getElementById(id),M=LedgerModel;
let db,records=[],lineId=M.LINES[0].id,tower=1,part='항공등',photos=[],processing=0,saving=false,dirty=false,current='linesView',previous='linesView';
const mainScene=TowerScene.mount($('mainScene')),editScene=TowerScene.mount($('editScene'));
const line=()=>M.LINES.find(l=>l.id===lineId),latest=p=>M.latest(records,lineId,tower,p),stamp=d=>new Date(d).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'});
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,5000);}
function req(r){return new Promise((resolve,reject)=>{r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function transaction(stores,mode,action){return new Promise((resolve,reject)=>{const tx=db.transaction(stores,mode);action(tx);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('저장이 취소되었습니다.'));});}
async function reload(){records=(await req(db.transaction('records').objectStore('records').getAll())).map(M.migrate);render();}
function confirmSave(summary){return confirm('1차 확인 — 저장하시겠습니까?\n'+summary)&&confirm('2차 확인 — 최종 저장할까요?\n'+summary);}
function show(view){current=view;['linesView','listView','towerView','settingsView'].forEach(id=>$(id).hidden=id!==view);render();window.scrollTo(0,0);}
function summary(s){return '항공구 '+s.ballCount+'개 · 항공등 '+(s.lightIntensity||'미등록')+' · 애자련 '+(s.insulatorType||'미등록')+' '+(s.stringCount?s.stringCount+'련':'련수 미등록')+' · 가공지선 '+M.groundLabel(s.groundWires)+' · 지형 '+(s.terrain||'미등록');}
function render(){
 $('lineCards').replaceChildren();M.LINES.forEach(l=>{const b=document.createElement('button');b.className='linecard';const title=document.createElement('strong');title.textContent=l.name;const detail=document.createElement('span');detail.textContent=l.count+'기 · 등록 '+new Set(records.filter(r=>r.lineId===l.id).map(r=>r.tower)).size+'기';const arrow=document.createElement('span');arrow.textContent='›';b.append(title,detail,arrow);b.onclick=()=>{lineId=l.id;$('search').value='';show('listView');};$('lineCards').append(b);});
 $('lineTitle').textContent=line().name;$('towerLine').textContent=line().name;$('towerTitle').textContent=tower+'호 철탑';$('towerCount').textContent=line().count;$('recorded').textContent=new Set(records.filter(r=>r.lineId===lineId).map(r=>r.tower)).size;
 $('towerGrid').replaceChildren();for(let n=1;n<=line().count;n++){if($('search').value&&!String(n).includes($('search').value.trim()))continue;const done=records.some(r=>r.lineId===lineId&&r.tower===n),b=document.createElement('button');b.className='towercell'+(done?' done':'');const title=document.createElement('span');title.textContent=n+'호';const small=document.createElement('small');small.textContent=done?'● 기록 있음':'○ 기록 없음';b.append(title,small);b.onclick=()=>{tower=n;mainScene.reset();show('towerView');};$('towerGrid').append(b);}if(!$('towerGrid').children.length)$('towerGrid').textContent='해당 호수가 없습니다.';
 const state=M.scene(records,lineId,tower);mainScene.update(state);$('sceneSummary').textContent=summary(state);
 $('partList').replaceChildren();M.PARTS.forEach(p=>{const r=latest(p),b=document.createElement('button');b.className='partrow';const a=document.createElement('span');a.textContent=p;const small=document.createElement('small');small.textContent=r?stamp(r.createdAt):'아직 등록하지 않았습니다';a.append(small);const value=document.createElement('span');value.className='value';value.textContent=M.label(r)+' ›';b.append(a,value);b.onclick=()=>openEditor(p);$('partList').append(b);});
}
function preview(){const s=M.scene(records,lineId,tower),v=$('choiceInput').value;if(part==='항공구')s.ballCount=Math.max(0,Math.min(100,Number($('ballInput').value)||0));if(part==='항공등')s.lightIntensity=v;if(part==='애자련'){s.insulatorType=selected('insulatorType');s.stringCount=Number(selected('stringCount'))||undefined;}if(part==='가공지선'){groundVisibility();const g=readGround();s.groundWires=M.validGround(g)?g:undefined;}if(part==='지형')s.terrain=v;editScene.update(s);$('editSummary').textContent=summary(s);}
function openEditor(p){part=p;dirty=false;photos=[];$('recordForm').reset();$('editorTower').textContent=line().name+' / '+tower+'호';$('partTitle').textContent=p;const last=latest(p),hasChoice=!!M.CHOICES[p]&&p!=='애자련';$('choiceField').hidden=!hasChoice;$('choiceInput').disabled=!hasChoice;$('choiceInput').required=hasChoice;$('choiceLabel').textContent=p==='항공등'?'항공등 광도':p==='애자련'?'애자련 형태':'지형';$('choiceInput').replaceChildren(new Option('선택해주세요',''),...(M.CHOICES[p]||[]).map(v=>new Option(v,v)));$('ballField').hidden=p!=='항공구';$('ballInput').disabled=p!=='항공구';$('ballInput').required=p==='항공구';$('ballInput').value=last?.ballCount??'';$('landOptions').hidden=p!=='부지';if(last){$('noteInput').value=last.note;photos=[...last.photos];$('choiceInput').value=last.lightIntensity||last.insulatorType||last.terrain||'';$('landOptions').querySelectorAll('input').forEach(el=>el.checked=last.land.includes(el.value));}$('insulatorFields').hidden=p!=='애자련';$('groundFields').hidden=p!=='가공지선';document.querySelectorAll('#insulatorFields input').forEach(el=>{el.disabled=p!=='애자련';el.checked=el.value===String(el.name==='insulatorType'?last?.insulatorType:last?.stringCount);});document.querySelectorAll('#groundFields input,#groundFields select,#groundFields button').forEach(el=>el.disabled=p!=='가공지선');fillGround(last?.groundWires);renderPhotos();renderHistory();$('editor').showModal();editScene.reset();preview();}
function renderHistory(){$('history').replaceChildren();const items=records.filter(r=>r.lineId===lineId&&r.tower===tower&&r.part===part).sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt));if(!items.length){$('history').textContent='등록 이력이 없습니다.';return;}items.forEach(r=>{const div=document.createElement('div');div.className='historyitem';const title=document.createElement('strong');title.textContent=M.label(r);const date=document.createElement('small');date.textContent=stamp(r.createdAt);const note=document.createElement('p');note.textContent=r.note;const pics=document.createElement('div');pics.className='historyphotos';r.photos.forEach((src,i)=>{const img=document.createElement('img');img.src=src;img.alt=part+' 사진 '+(i+1);img.loading='lazy';pics.append(img);});div.append(title,document.createElement('br'),date,note,pics);$('history').append(div);});}
function closeEditor(){if(processing||saving)return toast('사진 처리 또는 저장이 끝날 때까지 기다려주세요.');if(dirty&&!confirm('저장하지 않은 변경 내용을 닫을까요?'))return;$('editor').close();}
$('closeEditor').onclick=closeEditor;$('editor').addEventListener('cancel',e=>{e.preventDefault();closeEditor();});$('recordForm').oninput=()=>{dirty=true;preview();};
$('recordForm').onsubmit=async e=>{e.preventDefault();if(processing||saving)return;const choice=$('choiceInput').value,ballCount=Number($('ballInput').value);if(part==='항공구'&&(!Number.isInteger(ballCount)||ballCount<0||ballCount>100||$('ballInput').value===''))return toast('항공구 개수를 0~100 사이 정수로 입력해주세요.');if(part!=='애자련'&&M.CHOICES[part]&&!M.CHOICES[part].includes(choice))return toast('항목을 선택해주세요.');const insulatorType=selected('insulatorType'),stringCount=Number(selected('stringCount')),groundWires=readGround();if(part==='애자련'&&(!['내장','현수'].includes(insulatorType)||![1,2].includes(stringCount)))return toast('애자련 형태와 1련·2련을 선택해주세요.');if(part==='가공지선'&&!M.validGround(groundWires))return toast('가공지선 조수, 종류, 설치 위치를 선택해주세요.');const record={id:crypto.randomUUID(),lineId,tower,part,status:'등록',note:$('noteInput').value.trim(),land:part==='부지'?[...$('landOptions').querySelectorAll('input:checked')].map(x=>x.value):[],photos:[...photos],createdAt:new Date().toISOString(),...(part==='항공구'?{ballCount}:part==='항공등'?{lightIntensity:choice}:part==='애자련'?{insulatorType,stringCount}:part==='지형'?{terrain:choice}:part==='가공지선'?{groundWires}:{})};if(!confirmSave(line().name+' / '+tower+'호 / '+part+' / '+M.label(record)))return;saving=true;$('saveRecord').disabled=true;try{await transaction('records','readwrite',tx=>tx.objectStore('records').add(record));records.push(record);dirty=false;$('editor').close();render();toast('관리대장에 저장했습니다.');navigator.storage?.persist?.().catch(()=>{});}catch(err){toast('저장하지 못했습니다. 저장 공간을 확인해주세요.');}finally{saving=false;$('saveRecord').disabled=false;}};
$('back').onclick=()=>show('listView');$('linesBack').onclick=()=>show('linesView');$('search').oninput=render;$('settingsBtn').onclick=()=>{if(current!=='settingsView')previous=current;show('settingsView');};$('settingsBack').onclick=()=>show(previous);
$('exportBtn').onclick=()=>{const data={format:'tower-ledger',version:4,exportedAt:new Date().toISOString(),lines:M.LINES,records};const url=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='철탑대장-전체선로-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);$('backupStatus').textContent='두 선로 전체 백업을 요청했습니다. 파일 앱에서 저장 여부를 확인하세요.';};
$('importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());const incoming=M.validate(data);if(data.version<3&&!confirm('이전 버전 백업은 345KV 신남원-의령에 연결됩니다. 계속할까요?'))return;const ids=new Set(records.map(r=>r.id)),add=incoming.filter(r=>!ids.has(r.id));if(!confirmSave(add.length+'개 기록을 각 선로에 추가 (기존 기록 유지)'))return;await transaction('records','readwrite',tx=>add.forEach(r=>tx.objectStore('records').add(r)));await reload();toast(add.length+'개 기록을 불러왔습니다.');}catch(err){toast('불러오기 실패: '+err.message);}finally{e.target.value='';}};
window.addEventListener('beforeunload',e=>{if(dirty&&$('editor').open){e.preventDefault();e.returnValue='';}});
(async()=>{try{const open=indexedDB.open('tower-ledger-v1',1);open.onupgradeneeded=()=>{open.result.createObjectStore('records',{keyPath:'id'});open.result.createObjectStore('meta',{keyPath:'key'});};db=await req(open);await reload();}catch(err){toast('저장소를 열 수 없습니다. Safari 일반 모드에서 다시 열어주세요.');document.querySelectorAll('button,input,select').forEach(el=>el.disabled=true);}})();
function renderPhotos(){$('photoPreview').replaceChildren();photos.forEach((src,i)=>{const box=document.createElement('div');box.className='photoitem';const img=document.createElement('img');img.src=src;img.alt='첨부 사진 '+(i+1);const b=document.createElement('button');b.type='button';b.textContent='삭제';b.onclick=()=>{photos.splice(i,1);dirty=true;renderPhotos();};box.append(img,b);$('photoPreview').append(box);});}
function compress(file){return new Promise((resolve,reject)=>{if(!file.type.startsWith('image/'))return reject(new Error('이미지 파일을 선택해주세요.'));const url=URL.createObjectURL(file),im=new Image();im.onload=()=>{try{const scale=Math.min(1,1600/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*scale);c.height=Math.round(im.height*scale);c.getContext('2d').drawImage(im,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.8));}catch(e){reject(e);}finally{URL.revokeObjectURL(url);}};im.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('사진을 읽지 못했습니다. JPEG 사진으로 다시 선택해주세요.'));};im.src=url;});}
async function addPhotos(event){if(processing)return;processing++;$('saveRecord').disabled=true;try{const files=[...event.target.files];if(files.length+photos.length>8)throw new Error('한 기록에는 사진을 최대 8장 넣을 수 있습니다.');for(const file of files){photos.push(await compress(file));dirty=true;}renderPhotos();}catch(e){renderPhotos();toast(e.message);}finally{event.target.value='';processing--;$('saveRecord').disabled=false;}}

$('camera').onchange=addPhotos;$('gallery').onchange=addPhotos;

function selected(name){return document.querySelector('[name="'+name+'"]:checked')?.value||'';}
function readGround(){const count=Number(selected('groundCount'));return {count,direction:'1호→2호 정방향',...(count===1?{position:$('groundPosition').value,single:$('groundSingle').value}:count===2?{left:$('groundLeft').value,right:$('groundRight').value}:{})};}
function groundVisibility(){$('singleGround').hidden=selected('groundCount')!=='1';$('doubleGround').hidden=selected('groundCount')!=='2';}
function fillGround(g){document.querySelectorAll('[name="groundCount"]').forEach(el=>el.checked=el.value===String(g?.count));$('groundPosition').value=g?.position||'';$('groundSingle').value=g?.single||'';$('groundLeft').value=g?.left||'';$('groundRight').value=g?.right||'';groundVisibility();}
document.querySelectorAll('[data-ground]').forEach(b=>b.onclick=()=>{const preset=b.dataset.ground;fillGround(preset==='single'?{count:1,single:'OPGW',position:''}:{count:2,left:preset==='left'?'OPGW':'GW',right:preset==='left'?'GW':'OPGW'});dirty=true;preview();});
